from collections import deque

def shortestPathWithConsecutiveLimit(grid: list[list[str]], k: int) -> int:
    m = len(grid)
    n = len(grid[0])
    # (r, c, streak)
    start_state = (0, 0, 1)
    q = deque([(0, 0, 1, 0)])
    vis = set([start_state])
    while q:
