        if r == m - 1 and c == n - 1:
            return dist
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n:
                if grid[nr][nc] == grid[r][c]:
                    n_streak = streak + 1
                else:
                    n_streak = 1
                if n_streak <= k:
                    nxt = (nr, nc, n_streak)
                    if nxt not in vis:
                        vis.add(nxt)
                        q.append((nr, nc, n_streak, dist + 1))
