#include <vector>
#include <string>
#include <queue>
#include <tuple>

class Solution {
public:
    int shortestPathWithConsecutiveLimit(std::vector<std::vector<char>>& grid, int k) {
        int m = grid.size(), n = grid[0].size();
        std::vector<std::vector<std::vector<bool>>> vis(m, std::vector<std::vector<bool>>(n, std::vector<bool>(k + 1, false)));
        std::queue<std::tuple<int, int, int, int>> q;
        q.push({0, 0, 1, 0});
        vis[0][0][1] = true;
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!q.empty()) {
            auto [r, c, streak, dist] = q.front();
            q.pop();
            if (r == m - 1 && c == n - 1) return dist;
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                    int nStreak = (grid[nr][nc] == grid[r][c]) ? streak + 1 : 1;
                    if (nStreak <= k && !vis[nr][nc][nStreak]) {
                        vis[nr][nc][nStreak] = true;
                        q.push({nr, nc, nStreak, dist + 1});
                    }
                }
            }
        }
        return -1;
    }
};

import java.util.*;

class Solution {
    public int shortestPathWithConsecutiveLimit(char[][] grid, int k) {
        int m = grid.length, n = grid[0].length;
        boolean[][][] vis = new boolean[m][n][k + 1];
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{0, 0, 1, 0});
        vis[0][0][1] = true;
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1], streak = cur[2], dist = cur[3];
            if (r == m - 1 && c == n - 1) return dist;
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                    int nStreak = (grid[nr][nc] == grid[r][c]) ? streak + 1 : 1;
                    if (nStreak <= k && !vis[nr][nc][nStreak]) {
                        vis[nr][nc][nStreak] = true;
                        q.offer(new int[]{nr, nc, nStreak, dist + 1});
                    }
                }
            }
        }
        return -1;
    }
}

